import { join } from 'node:path'
import { defineConfig } from '@playwright/test'
import { desktopChrome, mockServer, mockURL } from './playwright.config.ts'

// The docs' screenshots: e2e/docs/media.spec.ts opens the populated cockpit on
// the mock build and writes a PNG of each screen the docs show into
// docs/assets/images, regenerated by hand and compared by nothing. It runs
// apart from playwright.config.ts, which leaves e2e/docs out, so neither
// `task e2e` nor CI rewrites a committed image.
export default defineConfig({
  testDir: 'e2e/docs',
  workers: 1,
  forbidOnly: true,
  retries: 0,
  reporter: 'list',
  projects: [
    {
      name: 'docs-media',
      // mediaDir is where the spec writes each image: the docs site's assets,
      // which its image shortcode reads.
      metadata: { mediaDir: join(import.meta.dirname, '..', 'docs', 'assets', 'images') },
      use: {
        ...desktopChrome,
        baseURL: mockURL,
        // One device pixel to a CSS pixel, so each image is exactly the
        // window's size, and dates read in English and in UTC on any machine.
        deviceScaleFactor: 1,
        timezoneId: 'UTC',
        locale: 'en-US',
      },
    },
  ],
  // Never a preview already listening on the mock build's port: one left
  // running by an e2e run would show the build of the moment it started, and
  // the images would show a cockpit older than the source.
  webServer: { ...mockServer, reuseExistingServer: false },
})
